    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, long taskIndex, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromCsv(String line) {
        // task_events: 13 columns (see ClusterData2011 schema)
        // We only need: timestamp, job ID, task index, event type.
        // timestamp(0), missing info(1), job ID(2), task index(3), machine ID(4), event type(5), ...
        String[] parts = line.split(",", -1);
        long ts = parseLong(parts, 0);
        long jobId = parseLong(parts, 2);
        long taskIndex = parseLong(parts, 3);
        int eventType = (int) parseLong(parts, 5);
        return new TaskEvent(ts, jobId, taskIndex, eventType);
    }

    private static long parseLong(String[] parts, int idx) {
        if (idx >= parts.length) {
            return -1L;
        }
        String s = parts[idx];
        if (s == null || s.isEmpty()) {
            return -1L;
        }
        return Long.parseLong(s);
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestampMicros=" + timestampMicros +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
